/*
 * Differential test of the translator, one instruction at a time.
 *
 * For every distinct instruction in the game (isa_cases.c, generated by
 * `m68k2c.py --isa-test`), run it from many random starting states both as the
 * translator's C and on Musashi, a reference 68000 emulator, and compare
 * registers, condition codes, memory and branch decisions.
 *
 *   isa_test <rom> [trials per instruction] [seed]
 *
 * Not compared:
 *  - flags the 68000 leaves undefined: N/V after ABCD/SBCD/NBCD, N/Z after a
 *    DIVU/DIVS overflow;
 *  - C after a DIVU/DIVS overflow: the Motorola manual says it is always cleared
 *    (which the translation does); Musashi leaves it unchanged.
 * Skipped trials: divide by zero (a trap), and word/long accesses at odd addresses
 * (an address error on the real 68000).
 */
#include "isa_test.h"
#include "m68k.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

M68KState R;
uint8_t g_ram[0x10000];
const uint8_t *g_rom;
uint32_t g_rom_size;

static uint8_t mram[0x10000];      /* Musashi's RAM */
static uint8_t init_ram[0x10000];
static int div_zero;
static int odd_access;   /* set by the Musashi side on an odd word/long access */

/* ---- C-side stubs: I/O reads as 0, writes ignored (same as the Musashi side) ---- */
uint32_t io_rd8(uint32_t a) { (void)a; return 0; }
uint32_t io_rd16(uint32_t a) { (void)a; return 0; }
void io_wr8(uint32_t a, uint32_t v) { (void)a; (void)v; }
void io_wr16(uint32_t a, uint32_t v) { (void)a; (void)v; }
void rt_exception(const char *what, uint32_t at) { (void)what; (void)at; div_zero = 1; }
void rt_call(uint32_t addr) { (void)addr; }
void rt_bad_jump(uint32_t t, uint32_t at) { (void)t; (void)at; }
void rt_rte(void) {}
uint32_t rt_get_sr(const Flags *f) { return 0x2700 | get_ccr(f); }
void rt_set_sr(Flags *f, uint32_t v) { set_ccr(f, v); }
void rt_service(void) {}
void rt_spcheck_fail(uint32_t e, uint32_t at) { (void)e; (void)at; }

/* ---- Musashi memory map: same rules as rd8/wr8 in m68k_rt.h ---- */
static unsigned int mread8(unsigned int a)
{
    a &= 0xFFFFFF;
    if (a >= 0xE00000) return mram[a & 0xFFFF];
    if (a < 0x400000) return a < g_rom_size ? g_rom[a] : 0xFF;
    return 0;
}
unsigned int m68k_read_memory_8(unsigned int a) { return mread8(a); }
unsigned int m68k_read_memory_16(unsigned int a) { if (a & 1) odd_access = 1; return (mread8(a) << 8) | mread8(a + 1); }
unsigned int m68k_read_memory_32(unsigned int a) { return (m68k_read_memory_16(a) << 16) | m68k_read_memory_16(a + 2); }
unsigned int m68k_read_disassembler_8(unsigned int a) { return mread8(a); }
unsigned int m68k_read_disassembler_16(unsigned int a) { return (mread8(a) << 8) | mread8(a + 1); }
unsigned int m68k_read_disassembler_32(unsigned int a) { return (m68k_read_disassembler_16(a) << 16) | m68k_read_disassembler_16(a + 2); }
static void mwrite8(unsigned int a, unsigned int v)
{
    a &= 0xFFFFFF;
    if (a >= 0xE00000) mram[a & 0xFFFF] = (uint8_t)v;
}
void m68k_write_memory_8(unsigned int a, unsigned int v) { mwrite8(a, v); }
void m68k_write_memory_16(unsigned int a, unsigned int v) { if (a & 1) odd_access = 1; mwrite8(a, v >> 8); mwrite8(a + 1, v); }
void m68k_write_memory_32(unsigned int a, unsigned int v) { m68k_write_memory_16(a, v >> 16); m68k_write_memory_16(a + 2, v & 0xFFFF); }

/* ---- random states ---- */
static uint64_t rng = 0x9E3779B97F4A7C15ull;
static uint32_t rnd(void)
{
    rng ^= rng << 13; rng ^= rng >> 7; rng ^= rng << 17;
    return (uint32_t)(rng >> 16);
}

static uint32_t rand_data(void)
{
    static const uint32_t edge[] = {0, 1, 0xFFFFFFFFu, 0x7F, 0x80, 0xFF, 0x7FFF, 0x8000, 0xFFFF,
                                    0x7FFFFFFFu, 0x80000000u, 0x00010000u, 0xFFFF0000u, 0xFF00FF00u};
    switch (rnd() % 10) {
    case 0: case 1: case 2: case 3: return rnd() ^ (rnd() << 16);
    case 4: case 5: return rnd() % 256 - 128;
    case 6: return rnd() % 64;
    case 7: return edge[rnd() % (sizeof edge / sizeof edge[0])];
    case 8: return rnd() & 0xFFFF;
    default: return (rnd() & 0xFFFF) | 0xFFFF0000u;
    }
}

typedef struct {
    uint32_t d[8], a[8];
    uint32_t ccr;
} State;

static uint32_t rand_addr(void)
{
    if (rnd() % 10 < 8) return 0xFF0000u | ((rnd() % 0xF000 + 0x800) & ~1u);  /* in RAM, room both ways */
    return rand_data();
}


/* Reset Musashi completely: after a pulse_reset its next execute() call only
 * finishes the reset sequence, so run that once here. */
static void reset_ref(void)
{
    m68k_pulse_reset();
    m68k_execute(1);
}

/* Run one instruction on the reference CPU from state s0. Returns the PC after it. */
static uint32_t run_ref(const IsaTest *T, const State *s0)
{
    int i;
    for (i = 0; i < 8; i++) m68k_set_reg((m68k_register_t)(M68K_REG_D0 + i), s0->d[i]);
    for (i = 0; i < 8; i++) m68k_set_reg((m68k_register_t)(M68K_REG_A0 + i), s0->a[i]);
    m68k_set_reg(M68K_REG_SR, 0x2700 | s0->ccr);
    m68k_set_reg(M68K_REG_PC, T->addr);
    odd_access = 0;
    m68k_execute(1);
    return m68k_get_reg(NULL, M68K_REG_PC);
}

static int ccr_mask_for(const char *op, uint32_t musashi_ccr)
{
    int mask = 0x1F;
    if (!strcmp(op, "abcd") || !strcmp(op, "sbcd") || !strcmp(op, "nbcd")) mask &= ~0x0A;      /* N, V */
    if ((!strcmp(op, "divu") || !strcmp(op, "divs")) && (musashi_ccr & 2)) mask &= ~0x0D;      /* N, Z, C */
    return mask;
}

static const char *ccr_str(uint32_t c)
{
    static char b[4][8];
    static int k;
    char *s = b[k++ & 3];
    snprintf(s, 8, "%c%c%c%c%c", c & 16 ? 'X' : '-', c & 8 ? 'N' : '-', c & 4 ? 'Z' : '-', c & 2 ? 'V' : '-', c & 1 ? 'C' : '-');
    return s;
}

int main(int argc, char **argv)
{
    FILE *f;
    static uint8_t rom[0x400000];
    long n;
    unsigned trials = argc > 2 ? (unsigned)atoi(argv[2]) : 32;
    unsigned t, k, i;
    unsigned long runs = 0, skipped = 0, skipped_odd = 0, failures = 0, failed_instr = 0, ref_resets = 0;
    if (argc < 2) { fprintf(stderr, "usage: isa_test <rom> [trials] [seed]\n"); return 2; }
    if (argc > 3) rng ^= (uint64_t)strtoull(argv[3], NULL, 0) * 0x2545F4914F6CDD1Dull;
    f = fopen(argv[1], "rb");
    if (!f) { perror(argv[1]); return 2; }
    n = (long)fread(rom, 1, sizeof rom, f);
    fclose(f);
    g_rom = rom;
    g_rom_size = (uint32_t)n;

    m68k_init();
    m68k_set_cpu_type(M68K_CPU_TYPE_68000);
    reset_ref();

    for (t = 0; t < isa_test_count; t++) {
        const IsaTest *T = &isa_tests[t];
        int bad_here = 0;
        for (i = 0; i < sizeof init_ram; i++) init_ram[i] = (uint8_t)rnd();
        for (k = 0; k < trials; k++) {
            State s0, sc, sm;
            Flags F;
            int taken = 0, mtaken;
            uint32_t mpc, msr, mask;
            for (i = 0; i < 8; i++) s0.d[i] = rand_data();
            for (i = 0; i < 8; i++) s0.a[i] = rand_addr();
            s0.a[7] = 0xFF0000u | ((rnd() % 0xE000 + 0x1000) & ~1u);
            s0.ccr = rnd() & 0x1F;

            /* translated C */
            memcpy(g_ram, init_ram, sizeof g_ram);
            memcpy(R.d, s0.d, sizeof R.d);
            memcpy(R.a, s0.a, sizeof R.a);
            R.sr = 0x2700;
            set_ccr(&F, s0.ccr);
            div_zero = 0;
            T->fn(&F, &taken);
            if (div_zero) { skipped++; continue; }
            memcpy(sc.d, R.d, sizeof sc.d);
            memcpy(sc.a, R.a, sizeof sc.a);
            sc.ccr = get_ccr(&F);

            /* reference */
            memcpy(mram, init_ram, sizeof mram);
            mpc = run_ref(T, &s0);
            if (mpc == T->addr) {
                /* the reference CPU did not run (left halted by an earlier trial): reset and retry */
                ref_resets++;
                reset_ref();
                memcpy(mram, init_ram, sizeof mram);
                mpc = run_ref(T, &s0);
            }
            if (odd_access) { skipped_odd++; continue; }
            for (i = 0; i < 8; i++) sm.d[i] = m68k_get_reg(NULL, (m68k_register_t)(M68K_REG_D0 + i));
            for (i = 0; i < 8; i++) sm.a[i] = m68k_get_reg(NULL, (m68k_register_t)(M68K_REG_A0 + i));
            msr = m68k_get_reg(NULL, M68K_REG_SR);
            sm.ccr = msr & 0x1F;
            mtaken = mpc != T->addr + T->len;
            runs++;

            mask = (uint32_t)ccr_mask_for(T->op, sm.ccr);
            if (memcmp(sc.d, sm.d, sizeof sc.d) || memcmp(sc.a, sm.a, sizeof sc.a) ||
                (sc.ccr & mask) != (sm.ccr & mask) || memcmp(g_ram, mram, sizeof mram) ||
                (taken != mtaken && (!strcmp(T->op, "bcc") || !strcmp(T->op, "dbcc")))) {
                failures++;
                if (bad_here++ < 2) {
                    printf("MISMATCH %06X %-30s ", T->addr, T->text);
                    printf("ccr in %s  C %s  ref %s", ccr_str(s0.ccr), ccr_str(sc.ccr), ccr_str(sm.ccr));
                    if (taken != mtaken) printf("  taken C %d ref %d (ref PC %06X)", taken, mtaken, mpc);
                    printf("\n");
                    for (i = 0; i < 8; i++)
                        if (sc.d[i] != sm.d[i]) printf("    D%u in %08X  C %08X  ref %08X\n", i, s0.d[i], sc.d[i], sm.d[i]);
                    for (i = 0; i < 8; i++)
                        if (sc.a[i] != sm.a[i]) printf("    A%u in %08X  C %08X  ref %08X\n", i, s0.a[i], sc.a[i], sm.a[i]);
                    for (i = 0; i < sizeof mram; i++)
                        if (g_ram[i] != mram[i]) {
                            printf("    RAM %06X  init %02X  C %02X  ref %02X\n", 0xFF0000 + i, init_ram[i], g_ram[i], mram[i]);
                            break;
                        }
                }
            }
        }
        if (bad_here) failed_instr++;
    }
    printf("%u instructions, %lu runs compared (skipped: %lu divide by zero, %lu odd-address word/long), "
           "%lu mismatches in %lu instructions\n",
           isa_test_count, runs, skipped, skipped_odd, failures, failed_instr);
    if (ref_resets) printf("(reference CPU needed %lu resets)\n", ref_resets);
    return failures ? 1 : 0;
}
